import json
import subprocess
import sys
import os

def run_command(command):
    try:
        result = subprocess.run(command, shell=True, check=False, text=True, capture_output=True)
        return {
            'name': command.split()[0] if command else '',
            'command': command,
            'exit_code': result.returncode,
            'output': result.stdout + result.stderr
        }
    except Exception as e:
        return {
            'name': command.split()[0] if command else '',
            'command': command,
            'exit_code': -1,
            'output': str(e)
        }

def generate_html_rows(jobs):
    rows = []
    for job_name, command in jobs.items():
        job_data = run_command(command)
        rows.append(f'<tr><td>{job_name}</td><td>{job_data["command"]}</td><td>{job_data["exit_code"]}</td><td><pre>{job_data["output"]}</pre></td></tr>')
    return '\n'.join(rows)

def main():
    if len(sys.argv) != 4:
        print("Usage: python job_report.py <jobs-json> <template-html> <output-html>")
        sys.exit(1)

    jobs_json = sys.argv[1]
    template_html = sys.argv[2]
    output_html = sys.argv[3]

    with open(jobs_json, 'r') as f:
        jobs = json.load(f)

    with open(template_html, 'r') as f:
        template = f.read()

    rows = generate_html_rows(jobs)
    output = template.replace('{{ROWS}}', rows)

    with open(output_html, 'w') as f:
        f.write(output)

if __name__ == "__main__":
    main()
